{"rules": [
 {
  "title": "Suspicious process from web service",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "web_parent": {
    "parent_process|contains": "httpd"
   },
   "shell_proc": {
    "process_name": ["sh", "bash", "cmd.exe", "powershell.exe"]
   },
   "condition": "web_parent AND shell_proc"
  },
  "confidence": 0.85,
  "rationale": "Web servers spawning shells is a strong indicator of remote code execution or web shell activity."
 },
 {
  "title": "Unauthorized service installation",
  "level": "high",
  "logsource": {
   "category": "service_event"
  },
  "detection": {
   "new_service": {
    "step": "create"
   },
   "not_standard": {
    "service_name|contains": "system"
   },
   "condition": "new_service AND NOT not_standard"
  },
  "confidence": 0.7,
  "rationale": "New service creation is a common persistence mechanism used by attackers."
 },
 {
  "title": "Internal lateral movement attempt",
  "level": "medium",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "internal_src": {
    "src_ip|contains": "10."
   },
   "target_port": {
    "dst_port": [445, 3389]
   },
   "condition": "internal_src AND target_port"
  },
  "confidence": 0.5,
  "rationale": "Traffic between internal hosts on SMB or RDP ports can indicate lateral movement or scanning."
 },
 {
  "title": "Decoy subnet access",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "decoy_hit": {
    "is_decoy": true
   },
   "condition": "decoy_hit"
  },
  "confidence": 0.95,
  "rationale": "Any interaction with a decoy asset is a high-fidelity indicator of malicious reconnaissance."
 },
 {
  "title": "Privileged process execution",
  "level": "medium",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "high_priv": {
    "privilege": "elevated"
   },
   "unusual_proc": {
    "process_name|contains": "temp"
   },
   "condition": "high_priv AND unusual_proc"
  },
  "confidence": 0.6,
  "rationale": "Elevated processes running from temporary directories are highly suspicious and often indicate malware."
 }
]}

{"rules": [
 {
  "title": "Unauthorized access to restricted zone",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "restricted_subnet": {
    "subnet": "restricted_zone_a"
   },
   "green_user_source": {
    "src_ip|contains": "green"
   },
   "condition": "restricted_subnet AND green_user_source"
  },
  "confidence": 0.9,
  "rationale": "Green users should not be initiating connections to the restricted_zone_a subnet."
 },
 {
  "title": "Suspicious service creation",
  "level": "medium",
  "logsource": {
   "category": "service_event"
  },
  "detection": {
   "new_service": {
    "service_name|contains": "temp"
   },
   "condition": "new_service"
  },
  "confidence": 0.5,
  "rationale": "Temporary or randomly named services are often used for persistence or lateral movement."
 },
 {
  "title": "Unexpected process from network service",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "shell_process": {
    "process_name": ["cmd.exe", "sh", "bash", "powershell.exe"]
   },
   "network_parent": {
    "parent_process|contains": "svc"
   },
   "condition": "shell_process AND network_parent"
  },
  "confidence": 0.8,
  "rationale": "Network services spawning interactive shells is a strong indicator of remote code execution."
 },
 {
  "title": "Direct connection to decoy host",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "decoy_hit": {
    "is_decoy": true
   },
   "condition": "decoy_hit"
  },
  "confidence": 0.95,
  "rationale": "Any interaction with a decoy host is highly suspicious and indicates reconnaissance."
 },
 {
  "title": "Privileged process execution in server zone",
  "level": "medium",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "elevated": {
    "privilege": "elevated"
   },
   "server_zone": {
    "zone": "server"
   },
   "condition": "elevated AND server_zone"
  },
  "confidence": 0.6,
  "rationale": "Monitoring elevated processes in the server zone helps detect potential privilege escalation."
 }
]}

