 "rules": [
  {
   "title": "Unauthorized access to restricted zone",
   "level": "high",
   "logsource": {
    "category": "network_connection"
   },
   "detection": {
    "restricted_subnet": {
     "subnet": "restricted_zone_a"
    },
    "not_green_service": {
     "src_ip|contains": "green"
    },
    "condition": "restricted_subnet AND NOT not_green_service"
   },
   "confidence": 0.9,
   "rationale": "Access to restricted_zone_a should only originate from authorized green services. Any other source is a violation."
  },
  {
   "title": "Decoy interaction detected",
   "level": "high",
   "logsource": {
    "category": "network_connection"
   },
   "detection": {
    "decoy_hit": {
     "is_decoy": true
    },
    "condition": "decoy_hit"
   },
   "confidence": 0.95,
   "rationale": "Interaction with a decoy indicates active reconnaissance or lateral movement attempts."
  },
  {
   "title": "Suspicious process from service parent",
   "level": "medium",
   "logsource": {
    "category": "process_creation"
   },
   "detection": {
    "service_parent": {
     "parent_process|contains": "service"
    },
    "suspicious_proc": {
     "process_name": [
      "sh",
      "bash",
      "cmd",
      "powershell"
     ]
    },
    "condition": "service_parent AND suspicious_proc"
   },
   "confidence": 0.7,
   "rationale": "Services spawning interactive shells is a common indicator of remote code execution."
  },
  {
   "title": "Privileged process creation on server",
   "level": "medium",
   "logsource": {
    "category": "process_creation"
   },
   "detection": {
    "elevated": {
     "privilege": "elevated"
    },
    "on_server": {
     "host_id|contains": "server"
    },
    "condition": "elevated AND on_server"
   },
   "confidence": 0.6,
   "rationale": "Unexpected elevated processes on critical server hosts can indicate privilege escalation."
  },
  {
   "title": "Outbound connection from restricted zone",
   "level": "high",
   "logsource": {
    "category": "network_connection"
   },
   "detection": {
    "in_restricted": {
     "subnet": "restricted_zone_a"
    },
    "is_outbound": {
     "dst_ip|contains": "external"
    },
    "condition": "in_restricted AND is_outbound"
   },
   "confidence": 0.8,
   "rationale": "Restricted zones should not initiate outbound connections to external IPs; potential data exfiltration."
  }
 ]
}
